#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/signalfd.h>
#include <errno.h>
#include <string.h>

// Helper to block specified signals globally
void block_signals(const sigset_t *mask) {
    if (sigprocmask(SIG_BLOCK, mask, NULL) == -1) {
        perror("sigprocmask failed");
        exit(EXIT_FAILURE);
    }
}

int main() {
    sigset_t mask;
    int sfd;
    struct signalfd_siginfo fdsi;
    ssize_t bytes_read;

    // 1. Define signals to capture (SIGINT and SIGTERM)
    sigemptyset(&mask);
    sigaddset(&mask, SIGINT);
    sigaddset(&mask, SIGTERM);

    // 2. Block these signals. They will be queued for signalfd.
    block_signals(&mask);

    // 3. Create the signalfd descriptor with non-blocking flag
    sfd = signalfd(-1, &mask, SFD_NONBLOCK);
    if (sfd == -1) {
        perror("signalfd failed");
        return EXIT_FAILURE;
    }

    printf("signalfd created: %d. Waiting for SIGINT (Ctrl+C) or SIGTERM.\n", sfd);
    printf("Please send SIGINT (Ctrl+C) now.\n");

    // Wait for a second and then attempt to read
    sleep(1);

    // 4. Read the signal info (if available)
    bytes_read = read(sfd, &fdsi, sizeof(struct signalfd_siginfo));

    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            printf("No signal captured yet (due to SFD_NONBLOCK).\n");
        } else {
            perror("read error");
        }
    } else if (bytes_read == sizeof(struct signalfd_siginfo)) {
        printf("Caught signal: %d. Sender PID: %d. Code: %d\n", 
               fdsi.ssi_signo, 
               fdsi.ssi_pid,
               fdsi.ssi_code);
    } else {
        fprintf(stderr, "Read incorrect number of bytes (%zd).\n", bytes_read);
    }

    close(sfd);
    return EXIT_SUCCESS;
}
